def P(text, style="Bodyx"):
    return Paragraph(text, styles[style])

def bullets(items):
    return [P("- " + item, "Bulletx") for item in items]

class ScreenMap(Flowable):
    def __init__(self, items, width=170*mm, height=86*mm):
        super().__init__(); self.items = items; self.width = width; self.height = height
    def draw(self):
        c = self.canv
        c.setStrokeColor(HexColor("#C8D4E1")); c.setFillColor(PALE); c.roundRect(0, 0, self.width, self.height, 7, fill=1, stroke=1)
        n = len(self.items); cols = 3 if n > 4 else 2; rows = (n + cols - 1) // cols
        bw = self.width / cols - 12*mm; bh = self.height / rows - 13*mm
        for i, (title, sub, color) in enumerate(self.items):
            col, row = i % cols, i // cols
            x = 7*mm + col*(self.width/cols); y = self.height - 7*mm - (row+1)*(bh+6*mm)
            c.setFillColor(colors.white); c.setStrokeColor(color); c.roundRect(x, y, bw, bh, 5, fill=1, stroke=1)
            c.setFillColor(color); c.roundRect(x, y+bh-9*mm, bw, 9*mm, 5, fill=1, stroke=0)
            c.setFillColor(colors.white); c.setFont("Helvetica-Bold", 8); c.drawCentredString(x+bw/2, y+bh-5.5*mm, title)
            c.setFillColor(INK); c.setFont("Helvetica", 7); 
            for j, line in enumerate(sub.split("|")):
                c.drawCentredString(x+bw/2, y+bh-15*mm-j*4*mm, line)

def Flow(title, body, color=TEAL):
    data = [[P(title, "H2x")], [P(body, "Bodyx")]]
    t = Table(data, colWidths=[170*mm])
    t.setStyle(TableStyle([("BACKGROUND", (0,0), (-1,-1), colors.white), ("BOX", (0,0), (-1,-1), .6, color), ("LEFTPADDING", (0,0), (-1,-1), 9), ("RIGHTPADDING", (0,0), (-1,-1), 9), ("TOPPADDING", (0,0), (-1,-1), 5), ("BOTTOMPADDING", (0,0), (-1,-1), 5)]))
    return t

def header_footer(canvas, doc):
    canvas.saveState()
    if doc.page > 1:
        canvas.setFillColor(NAVY); canvas.rect(0, A4[1]-12*mm, A4[0], 12*mm, fill=1, stroke=0)
        canvas.setFillColor(colors.white); canvas.setFont("Helvetica-Bold", 8); canvas.drawString(18*mm, A4[1]-8*mm, "CodeShell project comprehensive Guide")
        canvas.setFillColor(MUTED); canvas.setFont("Helvetica", 8); canvas.drawRightString(A4[0]-18*mm, 10*mm, f"Page {doc.page}")
        canvas.setStrokeColor(HexColor("#D7E0EA")); canvas.line(18*mm, 14*mm, A4[0]-18*mm, 14*mm)
    canvas.restoreState()

